"""Render CI results as Markdown for the GitHub Actions job summary.

Usage (each command prints Markdown to stdout; CI appends it to $GITHUB_STEP_SUMMARY):
    python ci_summary.py ruff     <ruff.json> <python_source_dir>...
    python ci_summary.py oxlint   <oxlint.json>
    python ci_summary.py junit    <title> <junit.xml>...
    python ci_summary.py coverage <coverage.json> <coverage-report.md> <threshold>
    python ci_summary.py vitest-coverage <coverage-summary.json>

Only the standard library is used so it runs on any runner without installs.
"""

from __future__ import annotations

import json
import sys
import xml.etree.ElementTree as ET
from collections import Counter
from pathlib import Path

MAX_ROWS = 50


def _score(issues: int, size: int) -> float:
    """Pylint-style score out of 10: 10 means no issues, never below 0."""
    if size <= 0:
        return 10.0
    return max(0.0, round(10.0 - (issues / size) * 10.0, 2))


def _badge(ok: bool) -> str:
    return "✅ Passed" if ok else "❌ Failed"


def _bar(percent: float) -> str:
    filled = int(round(percent / 10))
    return "█" * filled + "░" * (10 - filled)


def _count_statements(dirs: list[str]) -> int:
    lines = 0
    for directory in dirs:
        for path in Path(directory).rglob("*.py"):
            for line in path.read_text(encoding="utf-8", errors="ignore").splitlines():
                stripped = line.strip()
                if stripped and not stripped.startswith("#"):
                    lines += 1
    return lines


def ruff(report: str, *source_dirs: str) -> None:
    findings = json.loads(Path(report).read_text(encoding="utf-8") or "[]")
    statements = _count_statements(list(source_dirs))
    score = _score(len(findings), statements)
    files = len({item["filename"] for item in findings})

    print("## 🐍 Backend lint (ruff)\n")
    print("| Result | Issues | Files with issues | Lines of code scanned | Lint score |")
    print("|---|---:|---:|---:|---:|")
    print(f"| {_badge(not findings)} | {len(findings)} | {files} | {statements} | **{score:.2f} / 10** |\n")

    if not findings:
        print("No lint issues found. 🎉\n")
        return

    print("### Issues by rule\n")
    print("| Rule | Count | Description |")
    print("|---|---:|---|")
    by_rule = Counter(item["code"] or "syntax" for item in findings)
    messages = {item["code"] or "syntax": item["message"] for item in findings}
    for code, count in by_rule.most_common():
        print(f"| `{code}` | {count} | {messages[code]} |")

    print("\n<details><summary>All findings</summary>\n")
    print("| File | Line | Rule | Message |")
    print("|---|---:|---|---|")
    cwd = Path.cwd()
    for item in findings[:MAX_ROWS]:
        path = Path(item["filename"])
        rel = path.relative_to(cwd) if path.is_absolute() and path.is_relative_to(cwd) else path
        print(f"| `{rel.as_posix()}` | {item['location']['row']} | `{item['code']}` | {item['message']} |")
    if len(findings) > MAX_ROWS:
        print(f"\n…and {len(findings) - MAX_ROWS} more.")
    print("\n</details>\n")


def oxlint(report: str) -> None:
    data = json.loads(Path(report).read_text(encoding="utf-8") or "{}")
    diagnostics = data.get("diagnostics", []) if isinstance(data, dict) else data
    files_scanned = data.get("number_of_files", 0) if isinstance(data, dict) else 0
    errors = [d for d in diagnostics if d.get("severity") == "error"]
    warnings = [d for d in diagnostics if d.get("severity") != "error"]

    print("## ⚛️ Frontend lint (oxlint)\n")
    print("| Result | Errors | Warnings | Files scanned | Lint score |")
    print("|---|---:|---:|---:|---:|")
    # Errors weigh 5x warnings, like pylint.
    score = _score(5 * len(errors) + len(warnings), max(files_scanned, 1) * 10)
    print(f"| {_badge(not errors)} | {len(errors)} | {len(warnings)} | {files_scanned} | **{score:.2f} / 10** |\n")

    if diagnostics:
        print("| Severity | File | Line | Rule | Message |")
        print("|---|---|---:|---|---|")
        for item in diagnostics[:MAX_ROWS]:
            label = (item.get("labels") or [{}])[0]
            line = label.get("span", {}).get("line", "")
            message = item.get("message", "").replace("|", "\\|")
            print(f"| {item.get('severity', '')} | `{item.get('filename', '')}` | {line} "
                  f"| `{item.get('code', '')}` | {message} |")
        print()


def junit(title: str, *reports: str) -> None:
    totals = Counter()
    failures: list[tuple[str, str]] = []
    slowest: list[tuple[float, str]] = []
    for report in reports:
        if not Path(report).is_file():
            continue
        root = ET.parse(report).getroot()  # noqa: S314 - JUnit XML generated by this CI run
        for suite in root.iter("testsuite"):
            for key in ("tests", "failures", "errors", "skipped"):
                totals[key] += int(suite.get(key, 0))
            totals["time"] += float(suite.get("time", 0))
        for case in root.iter("testcase"):
            name = f"{case.get('classname', '')}::{case.get('name', '')}".strip(":")
            slowest.append((float(case.get("time", 0) or 0), name))
            for tag in ("failure", "error"):
                node = case.find(tag)
                if node is not None:
                    failures.append((name, (node.get("message") or "").splitlines()[0][:200]))

    failed = totals["failures"] + totals["errors"]
    passed = totals["tests"] - failed - totals["skipped"]
    rate = (passed / max(totals["tests"] - totals["skipped"], 1)) * 100

    print(f"## 🧪 {title}\n")
    print("| Result | Total | ✅ Passed | ❌ Failed | ⏭️ Skipped | Pass rate | Duration |")
    print("|---|---:|---:|---:|---:|---:|---:|")
    print(f"| {_badge(failed == 0 and totals['tests'] > 0)} | {totals['tests']} | {passed} | {failed} "
          f"| {totals['skipped']} | **{rate:.1f}%** | {totals['time']:.1f}s |\n")

    if failures:
        print("### Failed tests\n")
        print("| Test | Message |")
        print("|---|---|")
        for name, message in failures[:MAX_ROWS]:
            escaped = message.replace("|", "\\|")
            print(f"| `{name}` | {escaped} |")
        print()

    if slowest:
        print("<details><summary>Slowest 5 tests</summary>\n")
        print("| Test | Time |")
        print("|---|---:|")
        for seconds, name in sorted(slowest, reverse=True)[:5]:
            print(f"| `{name}` | {seconds:.2f}s |")
        print("\n</details>\n")


def coverage(report_json: str, report_md: str, threshold: str) -> None:
    totals = json.loads(Path(report_json).read_text(encoding="utf-8"))["totals"]
    percent = float(totals["percent_covered"])
    minimum = float(threshold)
    line_pct = 100.0 * totals["covered_lines"] / max(totals["num_statements"], 1)
    branch_pct = 100.0 * totals.get("covered_branches", 0) / max(totals.get("num_branches", 0), 1)

    print("## 📊 Backend coverage (unit + integration)\n")
    print("| Result | Total (line + branch) | Lines | Branches | Missed lines | Threshold |")
    print("|---|---:|---:|---:|---:|---:|")
    print(f"| {_badge(percent >= minimum)} | **{percent:.2f}%** `{_bar(percent)}` "
          f"| {line_pct:.2f}% ({totals['covered_lines']}/{totals['num_statements']}) "
          f"| {branch_pct:.2f}% ({totals.get('covered_branches', 0)}/{totals.get('num_branches', 0)}) "
          f"| {totals['missing_lines']} | {minimum:.0f}% |\n")
    print("<details><summary>Per-file coverage report</summary>\n")
    print(Path(report_md).read_text(encoding="utf-8"))
    print("\n</details>\n")


def vitest_coverage(summary_json: str) -> None:
    data = json.loads(Path(summary_json).read_text(encoding="utf-8"))
    total = data.pop("total")
    print("## 📊 Frontend coverage (vitest + v8)\n")
    print("| Metric | Covered | Total | Percent |")
    print("|---|---:|---:|---:|")
    for metric in ("lines", "statements", "functions", "branches"):
        item = total[metric]
        pct = item["pct"]
        print(f"| {metric.title()} | {item['covered']} | {item['total']} | **{pct:.2f}%** `{_bar(pct)}` |")

    print("\n<details><summary>Per-file coverage report</summary>\n")
    print("| File | Lines | Statements | Functions | Branches |")
    print("|---|---:|---:|---:|---:|")
    root = str(Path.cwd())
    for path, item in sorted(data.items()):
        name = Path(path.replace(root, "").lstrip("/\\")).as_posix()
        print(f"| `{name}` | {item['lines']['pct']:.1f}% | {item['statements']['pct']:.1f}% "
              f"| {item['functions']['pct']:.1f}% | {item['branches']['pct']:.1f}% |")
    print("\n</details>\n")


COMMANDS = {
    "ruff": ruff,
    "oxlint": oxlint,
    "junit": junit,
    "coverage": coverage,
    "vitest-coverage": vitest_coverage,
}

if __name__ == "__main__":
    if len(sys.argv) < 2 or sys.argv[1] not in COMMANDS:
        sys.exit(__doc__)
    sys.stdout.reconfigure(encoding="utf-8")
    COMMANDS[sys.argv[1]](*sys.argv[2:])
